mapper.select:
SELECT rod.id, rod.receipt_id, item.item_name, item.item_no, sku.id AS skuId, sku.sku_name, sku.sku_no, rod.quantity, item.unit, IF(rod.storage_shelf IS NULL OR rod.storage_shelf = '', '-', rod.storage_shelf) AS storage_shelf, rod.unit_price, (rod.quantity * rod.unit_price) AS totalPrice FROM wms_receipt_order_detail rod INNER JOIN wms_item_sku sku ON sku.id = rod.sku_id INNER JOIN wms_item item ON item.id = sku.item_id WHERE rod.receipt_id = #{dto.receiptId}
AND ( item.item_name LIKE CONCAT('%', #{dto.item}, '%') OR item.item_no LIKE CONCAT('%', #{dto.item}, '%') )
AND ( sku.sku_name LIKE CONCAT('%', #{dto.sku}, '%') OR sku.sku_no LIKE CONCAT('%', #{dto.sku}, '%') )
